import{_ as l,C as c,o as d,c as E,a2 as r,b as s,w as e,a as o,E as i,a3 as u,j as n}from"./chunks/framework.BaXgE4DV.js";const f=JSON.parse('{"title":"질문 제안과 선정","description":"","frontmatter":{},"headers":[],"relativePath":"features/questions.md","filePath":"features/questions.md","lastUpdated":1791389169000}'),h={name:"features/questions.md"};function C(q,t,A,B,p,b){const a=c("Mermaid");return d(),E("div",null,[t[2]||(t[2]=r('<h1 id="questions" tabindex="-1">질문 제안과 선정 <a class="header-anchor" href="#questions" aria-label="Permalink to &quot;질문 제안과 선정 {#questions}&quot;">​</a></h1><p>&quot;질문으로 쓰기&quot;에 나오는 질문은 사용자가 제안하고 운영자가 골라 선정합니다. <strong>선정된 질문만</strong> 다른 사용자에게 보이고, 사용자가 제안해 선정된 질문에는 제안자의 공개 이름이 함께 표시됩니다. 제안자는 처음 선정될 때 알림을 받고, 선정된 수에 따라 배지를 받습니다. → <a href="/grato-docs/decisions#adr-11">결정 기록 #11</a></p><table tabindex="0"><thead><tr><th>누가</th><th>무엇을</th><th>어디서</th></tr></thead><tbody><tr><td>사용자</td><td>질문 제안, 내 제안의 검토 상태 확인</td><td>질문으로 쓰기 화면, MyPage &quot;내가 제안한 질문&quot;</td></tr><tr><td>운영자 (<code>users/{uid}.isAdmin == true</code>)</td><td>선정(문구·종류 수정 가능), 반려, 숨김</td><td>관리자 페이지 &quot;질문&quot; 탭</td></tr><tr><td>서버</td><td>모든 쓰기: 검증, 한도, 상태 변경, 배지, 알림, 운영 기록</td><td><code>submitQuestion</code>, <code>reviewQuestion</code> callable</td></tr></tbody></table><h2 id="flow" tabindex="-1">흐름 <a class="header-anchor" href="#flow" aria-label="Permalink to &quot;흐름 {#flow}&quot;">​</a></h2>',4)),(d(),s(u,null,{default:e(()=>[i(a,{id:"mermaid-59",class:"mermaid",graph:"flowchart%20TD%0A%20%20U%5B%22%EC%82%AC%EC%9A%A9%EC%9E%90%3Cbr%2F%3E%EC%A7%88%EB%AC%B8%20%EC%A0%9C%EC%95%88%ED%95%98%EA%B8%B0%22%5D%20--%3E%7C%22submitQuestion(%7Btext%2C%20kind%7D)%22%7C%20V%7B%22%EA%B2%80%EC%A6%9D%3Cbr%2F%3E%EA%B8%B8%EC%9D%B4%20%C2%B7%20%EB%82%B4%EC%9A%A9%20%ED%95%84%ED%84%B0%20%C2%B7%20%ED%95%9C%EB%8F%84%20%C2%B7%20%EC%A4%91%EB%B3%B5%22%7D%0A%20%20V%20--%20%EA%B1%B0%EC%A0%88%20--%3E%20E%5B%22%EC%98%A4%EB%A5%98%20%EB%A9%94%EC%8B%9C%EC%A7%80%EB%A5%BC%20%EC%8B%9C%ED%8A%B8%EC%97%90%20%ED%91%9C%EC%8B%9C%22%5D%0A%20%20V%20--%20%ED%86%B5%EA%B3%BC%20--%3E%20P%5B(%22questions%2F%7Bid%7D%3Cbr%2F%3Estatus%3A%20pending%22)%5D%0A%20%20P%20-.-%3E%7C%22%EC%A0%9C%EC%95%88%EC%9E%90%20%EB%B3%B8%EC%9D%B8%EA%B3%BC%20%EC%9A%B4%EC%98%81%EC%9E%90%EB%A7%8C%20%EC%9D%BD%EC%9D%8C%22%7C%20M%5B%22MyPage%20%EB%82%B4%EA%B0%80%20%EC%A0%9C%EC%95%88%ED%95%9C%20%EC%A7%88%EB%AC%B8%3Cbr%2F%3E%EA%B2%80%ED%86%A0%20%EC%A4%91%22%5D%0A%20%20P%20--%3E%20A%5B%22%EC%9A%B4%EC%98%81%EC%9E%90%3Cbr%2F%3E%EA%B4%80%EB%A6%AC%EC%9E%90%20%ED%8E%98%EC%9D%B4%EC%A7%80%20'%EC%A7%88%EB%AC%B8'%22%5D%0A%20%20A%20--%3E%7C%22reviewQuestion%20approve%3Cbr%2F%3E(%EB%AC%B8%EA%B5%AC%C2%B7%EC%A2%85%EB%A5%98%20%EC%88%98%EC%A0%95%20%EA%B0%80%EB%8A%A5)%22%7C%20OK%5B(%22status%3A%20approved%22)%5D%0A%20%20A%20--%3E%7C%22reviewQuestion%20reject%3Cbr%2F%3E(%EC%82%AC%EC%9C%A0%20%EC%84%A0%ED%83%9D)%22%7C%20R%5B(%22status%3A%20rejected%22)%5D%0A%20%20OK%20--%3E%20W%5B%22%EC%A7%88%EB%AC%B8%EC%9C%BC%EB%A1%9C%20%EC%93%B0%EA%B8%B0%EC%97%90%20%ED%91%9C%EC%8B%9C%3Cbr%2F%3E%F0%9F%92%A1%20%EC%9D%B4%EB%A6%84%20%23%ED%83%9C%EA%B7%B8%EB%8B%98%EC%9D%98%20%EC%A7%88%EB%AC%B8%22%5D%0A%20%20OK%20--%3E%20B%5B%22%EB%B0%B0%EC%A7%80%20%ED%8F%89%EA%B0%80%3Cbr%2F%3Equestions_selected_1%20%2F%203%20%2F%2010%22%5D%0A%20%20OK%20--%3E%20N%5B%22%EC%B2%98%EC%9D%8C%20%EC%84%A0%EC%A0%95%EC%9D%B4%EB%A9%B4%20%EC%95%8C%EB%A6%BC%20%ED%95%9C%20%EB%B2%88%3Cbr%2F%3Equestion_selected%22%5D%0A%20%20OK%20--%3E%7C%22hide%22%7C%20H%5B(%22status%3A%20hidden%22)%5D%0A%20%20H%20--%3E%7C%22approve%20(%EB%8B%A4%EC%8B%9C%20%EC%84%A0%EC%A0%95)%22%7C%20OK%0A%20%20R%20-.-%3E%20RM%5B%22MyPage%3A%20%EB%B0%98%EB%A0%A4%EB%90%A8%20%2B%20%EC%82%AC%EC%9C%A0%22%5D%0A%20%20A%20-.-%3E%7C%22%EB%AA%A8%EB%93%A0%20%EC%9E%91%EC%97%85%22%7C%20L%5B(%22adminAuditLogs%22)%5D%0A"})]),fallback:e(()=>[...t[0]||(t[0]=[o(" Loading... ",-1)])]),_:1})),t[3]||(t[3]=n("h3",{id:"status",tabindex:"-1"},[o("상태 "),n("a",{class:"header-anchor",href:"#status","aria-label":'Permalink to "상태 {#status}"'},"​")],-1)),(d(),s(u,null,{default:e(()=>[i(a,{id:"mermaid-63",class:"mermaid",graph:"stateDiagram-v2%0A%20%20%5B*%5D%20--%3E%20pending%3A%20submitQuestion%20(%EC%82%AC%EC%9A%A9%EC%9E%90%20%EC%A0%9C%EC%95%88)%0A%20%20%5B*%5D%20--%3E%20approved%3A%20seedQuestions%20(%EA%B8%B0%EB%B3%B8%20%EC%A7%88%EB%AC%B8)%0A%20%20pending%20--%3E%20approved%3A%20approve%0A%20%20pending%20--%3E%20rejected%3A%20reject%0A%20%20approved%20--%3E%20hidden%3A%20hide%0A%20%20hidden%20--%3E%20approved%3A%20approve%0A"})]),fallback:e(()=>[...t[1]||(t[1]=[o(" Loading... ",-1)])]),_:1})),t[4]||(t[4]=r('<table tabindex="0"><thead><tr><th>상태</th><th>화면 이름</th><th>누가 볼 수 있나</th><th>질문으로 쓰기</th></tr></thead><tbody><tr><td><code>pending</code></td><td>검토 중</td><td>제안자, 운영자</td><td>나오지 않음</td></tr><tr><td><code>approved</code></td><td>선정됨</td><td>로그인한 모든 사용자</td><td>나옴</td></tr><tr><td><code>rejected</code></td><td>반려됨</td><td>제안자, 운영자</td><td>나오지 않음</td></tr><tr><td><code>hidden</code></td><td>숨김</td><td>제안자, 운영자</td><td>나오지 않음</td></tr></tbody></table><p>반려된 질문은 다시 선정할 수 없습니다. 제안자는 같은 질문을 새로 제안할 수 있습니다(반려·숨김 질문은 중복으로 보지 않음).</p><h2 id="suggest" tabindex="-1">질문 제안하기 <a class="header-anchor" href="#suggest" aria-label="Permalink to &quot;질문 제안하기 {#suggest}&quot;">​</a></h2><p>질문으로 쓰기 화면 아래의 &quot;좋은 질문이 떠올랐나요? 질문 제안하기&quot;와 MyPage &quot;내가 제안한 질문&quot;의 &quot;질문 제안하기&quot;에서 바텀 시트(<code>SuggestQuestionSheet</code>)를 엽니다.</p><ul><li><strong>종류</strong>: 첫 질문(&quot;오늘을 떠올리게 하는 질문&quot;) / 이어지는 질문(&quot;첫 답변을 더 깊게 묻는 질문&quot;). 질문으로 쓰기에서 열면 지금 보고 있는 단계의 종류가 미리 골라져 있습니다(쓰던 질문이 없을 때).</li><li><strong>질문</strong>: 최대 80자, 글자 수 표시. 보내기 전에 서버와 같은 방식으로 정리하고 5~80자인지 먼저 확인합니다.</li><li><strong>안내</strong>: &quot;운영자가 검토해 선정한 질문만 다른 사람들에게 보여요. 선정되면 공개 이름(예: 홍길동 #1234)이 질문과 함께 표시돼요.&quot;</li><li><strong>오류</strong>: 서버가 돌려준 메시지를 그대로 보여 줍니다. → <a href="/grato-docs/architecture/cloud-functions#question-errors">오류 메시지</a></li><li><strong>성공</strong>: &quot;제안해 주셔서 고마워요! 선정되면 알려드릴게요. 검토 결과는 마이페이지에서 볼 수 있어요.&quot; 시트를 닫았다 열어도 쓰던 질문은 남아 있고, 제안에 성공하면 비웁니다.</li><li>성공하면 분석 이벤트 <code>question_submitted</code>(<code>{ kind }</code>)를 남깁니다.</li></ul><h3 id="limits" tabindex="-1">제출 규칙 <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;제출 규칙 {#limits}&quot;">​</a></h3><p><code>submitQuestion</code>이 아래 순서로 확인합니다. 길이·내용 필터·종류에서 걸리면 Firestore를 읽지 않습니다.</p><table tabindex="0"><thead><tr><th>항목</th><th>기준</th><th>거절 메시지</th></tr></thead><tbody><tr><td>길이</td><td>정리한 뒤 5~80자 (코드 포인트 단위)</td><td>질문은 5~80자로 써주세요</td></tr><tr><td>내용 필터</td><td>욕설·혐오 표현, URL·도메인, 이메일, 8자리 이상 숫자(전화번호)</td><td>부적절한 표현이나 연락처는 질문에 넣을 수 없어요</td></tr><tr><td>종류</td><td><code>opening</code> 또는 <code>followup</code> (없으면 <code>opening</code>)</td><td>질문 종류가 올바르지 않아요</td></tr><tr><td>전체 검토 대기</td><td>모든 사용자의 <code>pending</code>이 300개 미만</td><td>지금은 검토를 기다리는 질문이 많아요. 잠시 후 다시 제안해주세요</td></tr><tr><td>하루 시도</td><td>사용자당 KST 하루 30번 (거절된 시도 포함)</td><td>오늘은 질문 제안을 너무 많이 시도했어요. 내일 다시 제안해주세요</td></tr><tr><td>하루 제안</td><td>사용자당 KST 하루 5개 (받아들여진 것만 셈)</td><td>오늘은 질문을 5개까지 제안할 수 있어요</td></tr><tr><td>내 검토 대기</td><td>사용자당 <code>pending</code> 20개 미만</td><td>검토 중인 질문이 많아요. 검토가 끝난 뒤 다시 제안해주세요</td></tr><tr><td>중복</td><td>검토 중이거나 선정된 질문과 같은 문구가 아님</td><td>이미 등록되었거나 검토 중인 질문이에요</td></tr></tbody></table><ul><li><strong>정리(정규화)</strong>: NFC, 보이지 않는 문자(폭 없는 공백, 한글 채움 문자 등)와 제어 문자 제거, 줄바꿈을 포함한 연속 공백을 한 칸으로, 앞뒤 공백 제거. 저장되는 <code>text</code>가 이 결과입니다.</li><li><strong>같은 문구</strong>: NFKC 후 보이지 않는 문자를 빼고 소문자로 바꾼 뒤 글자와 숫자만 남긴 키(<code>dupKey</code>)가 같으면 같은 질문으로 봅니다. &quot;오늘 감사한 일은?&quot;과 &quot;오늘 감사한 일은&quot;은 같은 질문입니다.</li><li>하루 한도는 <code>questionQuota/{uid}_{YYYYMMDD}</code>(KST) 문서로 세고, 하루 시도·하루 제안·내 검토 대기·중복 확인과 새 문서 생성은 한 트랜잭션에서 합니다. 동시에 여러 번 보내도 한도를 넘거나 같은 질문이 두 번 저장되지 않습니다.</li></ul><h3 id="filter" tabindex="-1">내용 필터 <a class="header-anchor" href="#filter" aria-label="Permalink to &quot;내용 필터 {#filter}&quot;">​</a></h3><p><code>functions/src/utils/contentFilter.ts</code>는 Firebase에 의존하지 않는 순수 모듈이라 나중에 댓글·이름에도 쓸 수 있습니다. 한국어·영어 욕설과 혐오 표현을 짧은 목록으로 막고, 띄어 쓰거나 구두점·숫자·기호를 끼워 넣거나 비슷한 글자로 바꿔 쓴 것도 정리한 뒤 비교합니다. &quot;시발점&quot;, &quot;감염병&quot;처럼 정상 단어는 허용 목록에 둡니다.</p><p>모든 질문은 운영자가 검토하므로, 필터는 놓치는 것보다 정상 문장을 막는 쪽을 더 조심합니다. 자세한 규칙은 <a href="/grato-docs/architecture/cloud-functions#content-filter">Cloud Functions: 내용 필터</a>에 있습니다.</p><h2 id="credit" tabindex="-1">제안자 표시 <a class="header-anchor" href="#credit" aria-label="Permalink to &quot;제안자 표시 {#credit}&quot;">​</a></h2><p>선정된 사용자 질문은 질문으로 쓰기의 질문 아래에 &quot;💡 홍길동 #1234님의 질문&quot;처럼 제안자의 공개 이름을 보여 줍니다. 기본 질문에는 표시하지 않습니다.</p><ul><li>이름(<code>authorPublicName</code>)은 제안할 때 <code>publicProfiles/{uid}.publicName</code>에서 복사하고, <strong>선정할 때 다시 읽어</strong> 갱신합니다. 선정한 뒤에 이름을 바꾸면 질문에 보이는 이름은 다음 선정 전까지 그대로입니다.</li><li>이름이 비어 있거나 내용 필터에 걸리면 이름을 저장하지 않고(null) 표시하지도 않습니다.</li><li><strong>선정할 때 이름 확인</strong>: 운영자 화면에 보이던 이름과 제안자의 지금 이름이 다르면 선정하지 않고 새 이름만 저장합니다. 운영자에게는 &quot;제안한 사람의 공개 이름이 바뀌었어요. 바뀐 이름을 확인한 뒤 다시 선정해주세요&quot;가 보이고, 목록을 다시 불러 새 이름을 보여 줍니다. 운영자가 확인하지 않은 이름이 질문과 함께 공개되지 않게 하기 위해서입니다.</li></ul><h2 id="my-questions" tabindex="-1">내가 제안한 질문 (MyPage) <a class="header-anchor" href="#my-questions" aria-label="Permalink to &quot;내가 제안한 질문 (MyPage) {#my-questions}&quot;">​</a></h2><p>MyPage의 &quot;내가 제안한 질문&quot; 카드(<code>id=&quot;questions&quot;</code>, 주소 <code>/mypage#questions</code>)입니다.</p><ul><li>본인 제안을 최신순으로 최대 50개 실시간으로 보여 줍니다. 처음에는 5개, 더 있으면 &quot;전체 보기 (n)&quot;.</li><li>상태 칩: <strong>검토 중</strong> / <strong>선정됨</strong> / <strong>반려됨</strong>(반려 사유가 있으면 함께 표시) / <strong>숨김</strong>. 종류(첫 질문 / 이어지는 질문)와 제안 날짜도 보여 줍니다.</li><li>제안한 질문이 없으면 &quot;첫 질문 제안하기&quot; 버튼을 보여 줍니다.</li><li>주소가 <code>#questions</code>로 끝나면 목록을 그린 뒤 이 카드로 스크롤합니다. 질문 선정 알림을 누르면 여기로 옵니다.</li></ul><h2 id="review" tabindex="-1">운영자 검토 <a class="header-anchor" href="#review" aria-label="Permalink to &quot;운영자 검토 {#review}&quot;">​</a></h2><p>관리자 페이지(<code>/admin</code>)의 첫 탭 &quot;질문&quot;(<code>QuestionManager</code>)에서 처리합니다. 모든 작업은 <code>reviewQuestion</code> callable로 하고, 운영자도 Firestore에 직접 쓰지 않습니다.</p><p>위쪽의 상태별 개수(검토 중 / 선정됨 / 숨김 / 반려됨)가 목록 탭을 겸합니다.</p><table tabindex="0"><thead><tr><th>목록</th><th>정렬</th><th>할 수 있는 일</th></tr></thead><tbody><tr><td>검토 중</td><td>오래된 순 (검토 대기열)</td><td>이대로 선정, 수정 후 선정(문구·종류), 반려(사유 100자 이내, 선택)</td></tr><tr><td>선정됨</td><td>사용자 질문 먼저, 최근 선정 순</td><td>숨기기 (확인 창)</td></tr><tr><td>숨김</td><td>사용자 질문 먼저</td><td>다시 선정</td></tr><tr><td>반려됨</td><td>최신순</td><td>보기만</td></tr></tbody></table><ul><li>카드에는 질문, 종류, 제안자의 공개 이름(없으면 &quot;이름 없음&quot;, 기본 질문은 &quot;기본 질문&quot;), 반려 사유가 보입니다.</li><li><strong>수정 후 선정</strong>: 고친 문구도 제안과 같은 길이·내용 필터를 거칩니다. 이미 선정된 다른 질문과 같은 문구면 &quot;이미 선정된 같은 질문이 있어요&quot;로 거절합니다. 고치기 전 제안 원문은 운영자만 읽을 수 있는 <code>questionOriginals/{id}</code>에 처음 한 번 남기고, 카드에 &quot;원문 (운영자만 보여요)&quot;로 보입니다. 공개되는 질문 문서에는 원문을 남기지 않습니다.</li><li>작업이 실패하면 카드에 서버 메시지를 보여 주고 목록을 다시 불러옵니다.</li><li>모든 작업은 같은 트랜잭션에서 <code>adminAuditLogs</code>에 기록됩니다. <strong>검토한 운영자의 정보는 질문 문서에 남지 않으므로</strong> 제안자는 누가 검토했는지 볼 수 없습니다.</li><li>기본 질문도 선정됨 목록에 함께 나오며, 숨기거나 다시 선정할 수 있습니다. 문구는 <code>questions.json</code>에서 고칩니다. → <a href="#system-questions">기본 질문</a></li></ul><h2 id="after-approval" tabindex="-1">선정 뒤에 일어나는 일 <a class="header-anchor" href="#after-approval" aria-label="Permalink to &quot;선정 뒤에 일어나는 일 {#after-approval}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>일</th><th>내용</th></tr></thead><tbody><tr><td>질문으로 쓰기</td><td>선정된 질문은 세션에 한 번 읽으므로, 다음에 앱을 열 때부터 나옵니다. → <a href="/grato-docs/features/guided-writing#pools">질문으로 쓰기</a></td></tr><tr><td>배지</td><td>사용자 질문이면 제안자의 배지를 평가합니다. 숨겨도 이미 받은 배지는 유지됩니다. → <a href="/grato-docs/features/stats-badges#question-badges">질문 배지</a></td></tr><tr><td>알림</td><td><strong>처음 선정될 때 한 번만</strong> 제안자에게 푸시를 보냅니다. 숨겼다가 다시 선정해도 다시 보내지 않습니다. → <a href="/grato-docs/features/notifications">알림</a></td></tr></tbody></table><p>선정 알림:</p><table tabindex="0"><thead><tr><th>항목</th><th>값</th></tr></thead><tbody><tr><td>제목</td><td>제안한 질문이 선정됐어요 🎉</td></tr><tr><td>본문</td><td>선정된 질문 문구</td></tr><tr><td>data</td><td><code>{ type: &quot;question_selected&quot;, questionId }</code></td></tr><tr><td>누르면</td><td><code>/mypage#questions</code></td></tr></tbody></table><p>반려는 알림을 보내지 않고, MyPage에서 사유와 함께 보입니다. 배지 평가와 알림은 검토가 끝난 뒤의 부가 작업이라, 실패해도 선정 자체는 취소되지 않습니다.</p><h3 id="질문-배지" tabindex="-1">질문 배지 <a class="header-anchor" href="#질문-배지" aria-label="Permalink to &quot;질문 배지&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ID</th><th>이름</th><th>아이콘</th><th>조건</th></tr></thead><tbody><tr><td><code>questions_selected_1</code></td><td>첫 질문 선정</td><td>💡</td><td>제안한 질문이 처음으로 선정됐어요</td></tr><tr><td><code>questions_selected_3</code></td><td>질문 큐레이터</td><td>✨</td><td>제안한 질문이 3번 선정됐어요</td></tr><tr><td><code>questions_selected_10</code></td><td>질문 장인</td><td>🏅</td><td>제안한 질문이 10번 선정됐어요</td></tr></tbody></table><p>조건 <code>questions_selected</code>는 제안자의 질문 중 <code>source == &quot;user&quot;</code>이고 <code>status == &quot;approved&quot;</code>인 것의 개수입니다.</p><h2 id="system-questions" tabindex="-1">기본 질문 <a class="header-anchor" href="#system-questions" aria-label="Permalink to &quot;기본 질문 {#system-questions}&quot;">​</a></h2><ul><li>원본은 <code>src/content/questions.json</code>(<code>{ &quot;opening&quot;: [30개], &quot;followup&quot;: [10개] }</code>)입니다.</li><li><code>seedQuestions</code> 스크립트가 <code>questions/system_opening_01..30</code>, <code>system_followup_01..10</code>으로 넣습니다(<code>source: &quot;system&quot;</code>, <code>authorId: null</code>, <code>status: &quot;approved&quot;</code>). 배포 때 실행합니다. → <a href="/grato-docs/operations/deploy#seed-questions">배포: 기본 질문 시드</a></li><li>운영자가 숨긴 기본 질문은 다시 시드해도 숨김으로 남습니다. 문구와 종류는 JSON 기준으로 되돌리므로 기본 질문 문구는 JSON에서 고칩니다.</li><li>앱도 같은 JSON을 들고 있어, 선정된 기본 질문을 읽지 못하면 대신 씁니다. → <a href="/grato-docs/features/guided-writing#pools">질문으로 쓰기</a></li></ul><h2 id="data" tabindex="-1">데이터와 권한 <a class="header-anchor" href="#data" aria-label="Permalink to &quot;데이터와 권한 {#data}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>저장소</th><th>내용</th><th>클라이언트</th></tr></thead><tbody><tr><td><code>questions/{id}</code></td><td>질문, 종류, 상태, 출처, 제안자, 표시 이름</td><td>선정된 질문: 로그인 사용자 / 그 밖: 제안자·운영자 읽기. 쓰기 없음</td></tr><tr><td><code>questionOriginals/{id}</code></td><td>운영자가 고치기 전 제안 원문</td><td>운영자만 읽기</td></tr><tr><td><code>questionQuota/{uid}_{YYYYMMDD}</code></td><td>하루 제안·시도 수 (TTL)</td><td>접근 불가</td></tr><tr><td><code>adminAuditLogs/{id}</code></td><td>운영자 작업 기록</td><td>접근 불가</td></tr></tbody></table><p>자세한 내용은 <a href="/grato-docs/architecture/data-model#questions">데이터 모델</a>, <a href="/grato-docs/architecture/security-rules#questions">보안 규칙</a>, <a href="/grato-docs/architecture/cloud-functions#questions">Cloud Functions</a>을 보세요.</p><h2 id="화면-문구" tabindex="-1">화면 문구 <a class="header-anchor" href="#화면-문구" aria-label="Permalink to &quot;화면 문구&quot;">​</a></h2><p>사용자에게 보이는 문구는 &quot;질문&quot;, &quot;제안&quot;, &quot;선정&quot;, &quot;검토&quot;로 설명합니다. &quot;AI&quot;나 &quot;인공지능&quot;이라는 표현은 쓰지 않습니다.</p>',38))])}const m=l(h,[["render",C]]);export{f as __pageData,m as default};
